const json = pm.response.json();

pm.test("Status is 201 Created", () => {
    pm.response.to.have.status(201);
});

pm.test("Location header points to the new transaction", () => {
    const location = pm.response.headers.get("Location");
    pm.expect(location).to.include(`/api/transactions/${json.id}`);
});

pm.test("Over-posting is ignored (server sets id and createdAt)", () => {
    pm.expect(json.id).to.not.eql(999);
    pm.expect(json.createdAt).to.not.include("1999");
});

// Save the server-assigned id, but only when a transaction was actually created.
// A 409 or 400 response has no "id", and saving it would overwrite transactionId with undefined.
if (pm.response.code === 201) {
    pm.collectionVariables.set("transactionId", json.id);
}

pm.test("Status is 400 Bad Request", () => {
    pm.response.to.have.status(400);
});

pm.test("Validation errors use JSON names", () => {
    const json = pm.response.json();
    pm.expect(json.errors).to.have.property("description");
    pm.expect(json.errors).to.have.property("amount");
});

pm.test("Status is 200 OK", () => {
    pm.response.to.have.status(200);
});

pm.test("List contains the created transaction", () => {
    const ids = pm.response.json().map(t => t.id);
    pm.expect(ids).to.include(pm.collectionVariables.get("transactionId"));
});

pm.test("Status is 200 OK", () => {
    pm.response.to.have.status(200);
});

pm.test("Every result is an Expense", () => {
    const results = pm.response.json();
    pm.expect(results.length).to.be.above(0);
    results.forEach(t => pm.expect(t.type).to.eql("Expense"));
});

pm.test("Status is 200 OK", () => {
    pm.response.to.have.status(200);
});

pm.test("Returns the requested transaction", () => {
    pm.expect(pm.response.json().id).to.eql(pm.collectionVariables.get("transactionId"));
});

pm.test("Status is 201 Created", () => {
    pm.response.to.have.status(201);
});

// Save this id for request 12 (duplicate check) and request 13 (cleanup), only on success.
if (pm.response.code === 201) {
    pm.collectionVariables.set("secondId", pm.response.json().id);
}

pm.test("Status is 409 Conflict (duplicate rule on update)", () => {
    pm.response.to.have.status(409);
});

pm.test("Status is 404 Not Found (already deleted)", () => {
    pm.response.to.have.status(404);
});
